mapper.select:
SELECT T1.PORTFOLIO_ID portfolioId, T1.PORTFOLIO_TYPE portfolioType, T1.PORTFOLIO_NAME portfolioName, T2.OPEN_TYPE openType, T2.RAISE_TYPE raiseType, T2.INVEST_NATURE investNature, T1.VDATE vdate, T1.MDATE mdate, T2.IS_GUARANTEE isGuarantee, T1.PROFIT_TYPE profitType FROM PTL_PORTFOLIO T1 LEFT JOIN PA_PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID
AND (T1.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{portfolioId},'%')) OR T1.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{portfolioId},'%')))
AND T1.PORTFOLIO_TYPE = #{portfolioType,jdbcType=VARCHAR}
AND T1.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}
AND T1.MDATE BETWEEN TO_DATE(#{startMDate},'YYYY-MM-DD') AND TO_DATE(#{endMDate},'YYYY-MM-DD')
AND T1.VDATE BETWEEN TO_DATE(#{startVDate},'YYYY-MM-DD') AND TO_DATE(#{endVDate},'YYYY-MM-DD')

SELECT ACCT_NO id, ACCT_NAME text, CCY object FROM STL_CAPACCT_INFO
ACCT_NO LIKE CONCAT('%',CONCAT(#{search},'%')) OR ACCT_NAME LIKE CONCAT('%',CONCAT(#{search},'%'))
AND ACCT_NO = #{initValue}

SELECT PORTFOLIO_ID id, PORTFOLIO_NAME text FROM PTL_PORTFOLIO
AND PORTFOLIO_ID = #{initValue}
AND PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%'))

SELECT SEC_ACCT_ID id, SEC_ACCT_NAME text FROM STL_SEC_ACCT_INFO
SEC_ACCT_ID LIKE CONCAT('%',CONCAT(#{search},'%'))
SEC_ACCT_ID = #{initValue}

SELECT
    PTL_BAG_ID
FROM
    PTL_PARAM_POOL_CONFIG

	(CLASSIFY_DIMENSION = #{classify_dimension_01}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_01},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_02}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_02},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_03}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_03},'%')))
	OR (CLASSIFY_DIMENSION = #{classify_dimension_04}
	AND CLASSIFY_DIMENSION_VAL LIKE CONCAT('%',CONCAT(#{dimension_04},'%')))

SELECT PORTFOLIO_ID portfolioId
FROM PTL_PORTFOLIO_AUTHORITY


		USER_ID = #{userId}
